begin;
select plan(23);
select has_function('concierge','plan_wire_count_v1',array['jsonb','integer'],'private bounded counter');
select has_function('concierge','plan_wire_budget_bytes_v1',array['jsonb'],'private closed Plan wire guard');
select is((select count(*)::integer from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='concierge' and p.proname in ('plan_wire_count_v1','plan_wire_budget_bytes_v1') and (has_function_privilege('anon',p.oid,'execute') or has_function_privilege('authenticated',p.oid,'execute') or has_function_privilege('service_role',p.oid,'execute'))),0,'no new raw helper privilege');
select is((select count(*)::integer from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='concierge' and p.proname in ('plan_wire_count_v1','plan_wire_budget_bytes_v1') and not coalesce(p.proconfig @> array['search_path=""'],false)),0,'empty helper search paths');
select is((select count(*)::integer from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='concierge' and p.proname in ('plan_wire_count_v1','plan_wire_budget_bytes_v1') and p.prosecdef),0,'counter does not introduce definer authority');
select is((select count(*)::integer from jsonb_object_keys(concierge.plan_command_fields())),26,'Plan26 unchanged');
select is((select count(*)::integer from jsonb_object_keys(concierge.care_command_fields())),13,'Care13 unchanged');
select is((select encode(sha256(convert_to(prosrc,'UTF8')),'hex') from pg_proc where oid='concierge.plan_command_base_v1(jsonb)'::regprocedure),'e1309a1f3e1fad3a952fe6a0786956d6237b2446bb37a5105ba03dbd42d29aa6','only pinned base size condition changes');
select ok(not has_function_privilege('authenticated','concierge.plan_command_base_v1(jsonb)','execute') and not has_function_privilege('service_role','concierge.plan_command_base_v1(jsonb)','execute'),'retained base stays private');
select is(concierge.plan_wire_budget_bytes_v1('{"schemaVersion":1,"action":"read_policy_v1"}'),45::bigint,'canonical actual policy command bytes');
select is(concierge.plan_wire_budget_bytes_v1('{"schemaVersion":1.00000,"action":"read_policy_v1"}'),45::bigint,'integral numeric scale does not redefine compact bytes');
select is((concierge.plan_wire_count_v1('{"schemaVersion":1,"action":"read_policy_v1"}',0))[2],3::bigint,'bounded value node count');
select throws_ok($$select concierge.plan_wire_budget_bytes_v1('{"schemaVersion":1,"action":"arbitrary_sql"}')$$,'P0001','concierge_invalid_input','unknown action rejects');
select throws_ok($$select concierge.plan_wire_budget_bytes_v1('{"schemaVersion":1,"action":"read_policy_v1","role":"owner"}')$$,'P0001','concierge_invalid_input','extra authority field rejects');
select throws_ok($$select concierge.plan_wire_budget_bytes_v1('{"schemaVersion":1.5,"action":"read_policy_v1"}')$$,'P0001','concierge_invalid_input','fractional enum rejects');
select throws_ok($$select concierge.plan_wire_budget_bytes_v1('{"schemaVersion":1,"action":"record_decision_v1","requestId":"10000000-0000-4000-8000-000000000001","expectedDecisionRevision":9007199254740992,"publicationVersion":1,"decisionId":"choice","choice":"approved","reason":null}')$$,'P0001','concierge_invalid_input','unsafe numeric rejects');
select throws_ok($$select concierge.plan_wire_budget_bytes_v1('null')$$,'P0001','concierge_invalid_input','null command rejects');
create temporary table wire_budget_compressed(v jsonb);
insert into wire_budget_compressed values(jsonb_build_object('schemaVersion',1,'action','read_policy_v1','extra',repeat('x',3000000)));
select ok((select pg_column_size(v)<1000000 from wire_budget_compressed),'compressed physical size is not the wire metric');
select ok((select octet_length(v::text)>3000000 from wire_budget_compressed),'uncompressed representation exceeds derived guard');
select throws_ok($$select concierge.plan_wire_budget_bytes_v1(v) from wire_budget_compressed$$,'P0001','concierge_invalid_input','compressed excess fails closed');
create temporary table wire_budget_boundary(name text primary key,command jsonb);
do $$declare cmd jsonb:=jsonb_build_object('schemaVersion',1,'action','save_draft_v1','requestId','10000000-0000-4000-8000-000000000001','draftId','10000000-0000-4000-8000-000000000002','expectedContentRevision',0,'expectedAssignmentRevision',0,'kind','care_plan','content',concierge.plan_empty_content());gap integer;fill integer;last_index integer;padding text;begin
 while concierge.review_bytes(cmd)<500000 loop
  cmd:=jsonb_set(cmd,'{content,consultationSections}',(cmd#>'{content,consultationSections}')||jsonb_build_array(jsonb_build_object('title','synthetic padding','body','')));
  gap:=500000-concierge.review_bytes(cmd);if gap<0 then raise exception 'boundary_builder';end if;fill:=least(16000,gap);padding:=repeat('🧴',fill/4)||case fill%4 when 1 then 'x' when 2 then 'é' when 3 then '☀' else '' end;last_index:=jsonb_array_length(cmd#>'{content,consultationSections}')-1;
  cmd:=jsonb_set(cmd,array['content','consultationSections',last_index::text,'body'],to_jsonb(padding));
 end loop;
 insert into wire_budget_boundary values('exact',cmd);
 cmd:=jsonb_set(cmd,array['content','consultationSections',last_index::text,'body'],to_jsonb(padding||'x'));insert into wire_budget_boundary values('over',cmd);
end $$;
select is((select concierge.plan_wire_budget_bytes_v1(command) from wire_budget_boundary where name='exact'),500000::bigint,'actual closed source-valid500000 boundary accepts');
select throws_ok($$select concierge.plan_wire_budget_bytes_v1(command) from wire_budget_boundary where name='over'$$,'P0001','concierge_invalid_input','500001 rejects');
select throws_ok($$select concierge.plan_wire_count_v1('[[[[[[[[[[0]]]]]]]]]]',0)$$,'P0001','concierge_invalid_input','depth above ten levels rejects');
select * from finish();
rollback;
